import{_ as n,y as i,a as d,o as l,a2 as r,D as s,g as e,I as a}from"./chunks/framework.DCcmcJcL.js";const y=JSON.parse('{"title":"Products","description":"","frontmatter":{},"headers":[],"relativePath":"product-types/products.md","filePath":"product-types/products.md","lastUpdated":1789441803000}'),h={name:"product-types/products.md"};function c(p,t,u,g,m,f){const o=i("ImagePopup");return l(),d("div",null,[t[5]||(t[5]=r('<h1 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h1><p>Products are what you sell. Every product has a <strong>type</strong>, which decides how shoppers buy it, and an <strong>attribute family</strong>, which decides which fields you fill in. This page covers what every product shares: the products list, creating a product and the sections of the edit screen. Each product type has its own page for what&#39;s specific to it.</p><h2 id="product-types" tabindex="-1">Product types <a class="header-anchor" href="#product-types" aria-label="Permalink to &quot;Product types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="./simple-product.html">Simple</a></td><td>One physical item with no choices to make, such as a desk lamp.</td></tr><tr><td><a href="./configurable-product.html">Configurable</a></td><td>An item sold in variants, such as a shirt in several colors and sizes.</td></tr><tr><td><a href="./grouped-product.html">Grouped</a></td><td>A set of simple products shown on one page, each bought in its own quantity.</td></tr><tr><td><a href="./bundle-product.html">Bundle</a></td><td>A kit the shopper puts together from options, such as an outfit with a choice of shoes.</td></tr><tr><td><a href="./downloadable-product.html">Downloadable</a></td><td>Digital files, such as e-books, music or software.</td></tr><tr><td><a href="./virtual-product.html">Virtual</a></td><td>Services, memberships and passes that aren&#39;t shipped.</td></tr><tr><td><a href="./booking-product.html">Booking</a></td><td>Appointments, events, rentals and table reservations.</td></tr></tbody></table><h2 id="the-products-list" tabindex="-1">The products list <a class="header-anchor" href="#the-products-list" aria-label="Permalink to &quot;The products list&quot;">​</a></h2><p>Go to <strong>Catalog &gt;&gt; Products</strong>.</p>',6)),s(o,{src:"/images/products/products-grid.png",alt:"The products list under Catalog >> Products"}),t[6]||(t[6]=r('<p>Each row shows three columns:</p><ul><li><strong>Name / SKU / Attribute Family</strong>.</li><li><strong>Image / Price / Quantity / ID</strong>: the main image with the number of images on it, the price, and the stock: <ul><li>the quantity available, such as <strong>500 Available</strong>, or <strong>Out of Stock</strong>, for products that keep stock;</li><li><strong>Stock Disabled</strong> for downloadable and booking products, and for products with <strong>Manage Stock</strong> switched off;</li><li><strong>N/A</strong> for configurable, grouped and bundle products, whose stock is kept on the products they contain.</li></ul></li><li><strong>Status / Category / Type</strong>: <strong>Active</strong> or <strong>Disable</strong>, the product&#39;s categories, and its type.</li></ul><p>The variants of a configurable product are listed too, as simple products, because each variant has its own SKU, price and stock.</p><h3 id="find-products" tabindex="-1">Find products <a class="header-anchor" href="#find-products" aria-label="Permalink to &quot;Find products&quot;">​</a></h3><ul><li><strong>Search:</strong> type in the search box to find products by name.</li><li><strong>Filter:</strong> click <strong>Filter</strong> and filter by <strong>Name</strong>, <strong>SKU</strong>, <strong>Attribute Family</strong>, <strong>Price</strong>, <strong>ID</strong>, <strong>Status</strong>, <strong>Category</strong> or <strong>Type</strong>. When you have more than one channel, you can also filter by <strong>Channel</strong>.</li><li><strong>Sort:</strong> click <strong>Name</strong>, <strong>SKU</strong>, <strong>Price</strong>, <strong>Quantity</strong>, <strong>ID</strong>, <strong>Status</strong> or <strong>Type</strong> in the header row.</li></ul>',5)),s(o,{src:"/images/products/products-filter.png",alt:"The Filters panel of the products list"}),t[7]||(t[7]=r('<h3 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h3><ul><li><strong>Copy</strong> (the copy icon) creates a copy of the product. See <a href="#copying-a-product">Copying a product</a>.</li><li><strong>Edit</strong> (the arrow) opens the product&#39;s edit screen.</li></ul><h3 id="change-several-products-at-once" tabindex="-1">Change several products at once <a class="header-anchor" href="#change-several-products-at-once" aria-label="Permalink to &quot;Change several products at once&quot;">​</a></h3><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Tick the products.</li><li>Open <strong>Select Action</strong>.</li><li>Choose <strong>Delete</strong>, or point to <strong>Update Status</strong> and choose <strong>Active</strong> or <strong>Disable</strong>.</li></ol>',4)),s(o,{src:"/images/products/products-mass-actions.png",alt:"Select Action menu with Delete and Update Status for two ticked products"}),t[8]||(t[8]=r('<p>Deleting a product can&#39;t be undone.</p><h3 id="export-the-list" tabindex="-1">Export the list <a class="header-anchor" href="#export-the-list" aria-label="Permalink to &quot;Export the list&quot;">​</a></h3><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Click <strong>Export</strong>. The <strong>Download</strong> dialog opens.</li><li>Choose <strong>CSV</strong>, <strong>XLS</strong> or <strong>XLSX</strong>.</li><li>Click <strong>Export</strong>.</li></ol><p>The file lists the products with every attribute value, so you can check or share your catalog in a spreadsheet. To bring products in from a file, see <a href="./../settings/data-transfer.html">Data Transfer</a>.</p><h3 id="copying-a-product" tabindex="-1">Copying a product <a class="header-anchor" href="#copying-a-product" aria-label="Permalink to &quot;Copying a product&quot;">​</a></h3><p>A copy saves time when a new product is close to an existing one. The copy:</p><ul><li>is named <strong>Copy Of</strong> followed by the original name;</li><li>gets a URL key starting with <strong>copy-of-</strong> and a temporary SKU, and its <strong>Product Number</strong>, if it has one, also starts with <strong>copy-of-</strong>;</li><li>is saved <strong>disabled</strong>, with the original&#39;s details, images, videos, channels, categories, stock, customer group prices, related products and customizable options.</li></ul><p>Copying a configurable product also copies each of its variants, and each copied variant starts disabled with a temporary SKU. A variant can&#39;t be copied on its own.</p><p>Open the copy and change its <strong>SKU</strong>, <strong>Name</strong>, <strong>URL Key</strong> and <strong>Product Number</strong>. Then switch <strong>Status</strong> on.</p><h2 id="create-a-product" tabindex="-1">Create a product <a class="header-anchor" href="#create-a-product" aria-label="Permalink to &quot;Create a product&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Click <strong>Create Product</strong>. The <strong>Create New Product</strong> dialog opens.</li><li>Choose the <strong>Type</strong>.</li><li>Choose the <strong>Family</strong>, the attribute family whose fields the product uses.</li><li>Enter the <strong>SKU</strong>, a unique code for the product. Use letters, numbers and hyphens, such as <code>desk-lamp-classic</code>.</li><li>Click <strong>Save Product</strong>. The product is created and its edit screen opens.</li></ol>',11)),s(o,{src:"/images/products/products-create.png",alt:"Create New Product dialog with Type, Family and SKU"}),t[9]||(t[9]=r('<p>A configurable product has one more step before it&#39;s created, where you choose the attribute values its variants are made from. See <a href="./configurable-product.html">Configurable Product</a>.</p><div class="warning custom-block"><p class="custom-block-title">The type and family are fixed</p><p>The edit screen has no way to change a product&#39;s type or attribute family. If you chose the wrong one, delete the product and create it again.</p></div><h2 id="the-edit-screen" tabindex="-1">The edit screen <a class="header-anchor" href="#the-edit-screen" aria-label="Permalink to &quot;The edit screen&quot;">​</a></h2><p>The edit screen opens after you create a product, or when you click <strong>Edit</strong> on a row.</p>',4)),s(o,{src:"/images/products/products-edit.png",alt:"Edit Product screen with the General and Price sections"}),t[10]||(t[10]=r('<p>At the top:</p><ul><li><strong>Back</strong> returns to the products list without saving.</li><li><strong>Preview</strong> opens the product on the storefront. It appears once the product is enabled, visible individually and has a URL key.</li><li><strong>Save Product</strong> saves every section and returns to the products list.</li></ul><p>Below the title are the channel and language selectors. The channel selector appears when you have more than one channel, and the language selector when the channel has more than one language. A field with a language badge, such as <strong>Name</strong>, is saved separately for each language, and a field with a channel badge is saved separately for each channel. Choose the channel and language before you edit these fields.</p><p>The sections come from the product&#39;s attribute family, so the fields you see depend on the family and the type. The sections below are those of the <strong>Default</strong> family, in the order the screen shows them: the main column first, then the side column.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><p>The product&#39;s identity:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>SKU</strong></td><td>The unique code you entered when creating the product.</td></tr><tr><td><strong>Product Number</strong></td><td>An optional number of your own, such as a manufacturer&#39;s part number. It must be unique.</td></tr><tr><td><strong>Name</strong></td><td>The name shoppers see.</td></tr><tr><td><strong>URL Key</strong></td><td>The last part of the product&#39;s storefront address. It&#39;s filled in from the name as you type, and it must be unique.</td></tr><tr><td><strong>Tax Category</strong></td><td>The tax category whose rates apply to the product. See <a href="./../settings/taxes.html">Taxes</a>.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Renaming changes the address</p><p>Typing in <strong>Name</strong> rewrites the <strong>URL Key</strong>, so renaming a product also changes its storefront address. Check the <strong>URL Key</strong> before you save.</p></div><p>The <strong>Default</strong> family also adds <strong>Color</strong>, <strong>Size</strong> and <strong>Brand</strong> here. Brand isn&#39;t a separate feature: it&#39;s a select attribute, so you add brands as its options under <strong>Catalog &gt;&gt; Attributes</strong>. See <a href="./../attribute/product-attribute.html">Product Attributes</a>.</p><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>Enter the <strong>Short Description</strong> and the <strong>Description</strong> in the text editors. On the product page, the short description appears beside the images and the description further down.</p>',11)),s(o,{src:"/images/products/products-description.png",alt:"Description section with the Short Description and Description editors"}),t[11]||(t[11]=r('<p>When Generative AI (Magic AI) is set up, the <strong>Magic AI</strong> button in each editor writes the text for you. See <a href="./../generative-ai/generate-content.html">Generate Text Content</a>.</p><h3 id="meta-description" tabindex="-1">Meta Description <a class="header-anchor" href="#meta-description" aria-label="Permalink to &quot;Meta Description&quot;">​</a></h3><p>The fields search engines read. A preview at the top of the section shows how the product could appear in search results, and it updates as you type.</p><ul><li><strong>Meta Title</strong>: the title of the product page, shown in the browser tab and search results. When it&#39;s empty, the product name is used.</li><li><strong>Meta Keywords</strong>: words and phrases the product should be found by.</li><li><strong>Meta Description</strong>: the summary shown under the title in search results. When it&#39;s empty, the start of the description is used.</li></ul>',4)),s(o,{src:"/images/products/products-meta-description.png",alt:"Meta Description section with the search result preview"}),t[12]||(t[12]=r('<h3 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h3><p>Click <strong>Add Image</strong> to upload images in JPG, PNG, WebP or BMP format. The recommended size is 560 × 609 pixels. The empty tiles are labelled <strong>Front</strong>, <strong>Next</strong>, <strong>Zoom</strong>, <strong>Use Cases</strong> and <strong>Size</strong> to suggest the views to upload.</p><ul><li><strong>Reorder:</strong> drag an image to a new position. The first image is the product&#39;s main image.</li><li><strong>Remove:</strong> point to the image and click the bin icon.</li><li><strong>Alt text and file name:</strong> point to the image and click the pencil icon. In the panel that opens, enter the <strong>Alt Text</strong> and <strong>File Name</strong>, or upload a new file under <strong>Replace Image</strong>.</li></ul><p>When image generation is set up, the <strong>Magic AI</strong> button next to <strong>Add Image</strong> creates product images from a description. See <a href="./../generative-ai/generate-images.html">Generate Product Images</a>.</p><h3 id="videos" tabindex="-1">Videos <a class="header-anchor" href="#videos" aria-label="Permalink to &quot;Videos&quot;">​</a></h3><p>Click <strong>Add Video</strong> to upload videos, such as MP4 or WebM files. Drag the videos to reorder them. The largest video you can upload is set by <strong>Allowed File Upload Size</strong> in the <a href="./../configure/attribute.html">Attribute</a> configuration.</p>',6)),s(o,{src:"/images/products/products-images-videos.png",alt:"Images and Videos sections of the edit screen"}),t[13]||(t[13]=r('<h3 id="the-product-type-s-section" tabindex="-1">The product type&#39;s section <a class="header-anchor" href="#the-product-type-s-section" aria-label="Permalink to &quot;The product type&#39;s section&quot;">​</a></h3><p>Next comes the section for the product&#39;s type, such as <strong>Variations</strong> for a configurable product or <strong>Downloadable Links</strong> for a downloadable one. Simple and virtual products get <strong>Customizable Item</strong>. Each type&#39;s page describes its section.</p><h3 id="related-up-sell-and-cross-sell-products" tabindex="-1">Related, up-sell and cross-sell products <a class="header-anchor" href="#related-up-sell-and-cross-sell-products" aria-label="Permalink to &quot;Related, up-sell and cross-sell products&quot;">​</a></h3><p>Three sections let you suggest other products:</p><table tabindex="0"><thead><tr><th>Section</th><th>Where shoppers see it</th></tr></thead><tbody><tr><td><strong>Related Products</strong></td><td>On this product&#39;s page.</td></tr><tr><td><strong>Up-Sell Products</strong></td><td>On this product&#39;s page, as better or pricier alternatives.</td></tr><tr><td><strong>Cross-Sell Products</strong></td><td>On the cart page, as add-ons when this product is in the cart.</td></tr></tbody></table>',5)),s(o,{src:"/images/products/products-related-up-cross-sells.png",alt:"Related Products, Up-Sell Products and Cross-Sell Products sections"}),t[14]||(t[14]=e("p",null,"To add products to one of these sections:",-1)),e("ol",null,[t[1]||(t[1]=e("li",null,[e("p",null,[a("Click "),e("strong",null,"Add Product"),a(" in the section. The "),e("strong",null,"Select Products"),a(" panel opens.")])],-1)),t[2]||(t[2]=e("li",null,[e("p",null,"Search for the products by name.")],-1)),t[3]||(t[3]=e("li",null,[e("p",null,"Tick the products.")],-1)),e("li",null,[t[0]||(t[0]=e("p",null,[a("Click "),e("strong",null,"Add Selected Product"),a(".")],-1)),s(o,{src:"/images/products/products-add-product.png",alt:"Select Products panel with search results ticked for adding"})]),t[4]||(t[4]=e("li",null,[e("p",null,[a("Click "),e("strong",null,"Save Product"),a(".")])],-1))]),t[15]||(t[15]=r('<p>To remove a product from a section, click <strong>Delete</strong> on its row.</p><p>The number of related, up-sell and cross-sell products shoppers see is set in <a href="./../configure/product-view-page.html">Product View Page</a> and <a href="./../configure/cart-view-page.html">Cart View Page</a>. Cross-sell products appear only while <strong>Cross sell Products</strong> is on in <a href="./../configure/checkout.html#shopping-cart">Checkout</a>.</p><h3 id="price" tabindex="-1">Price <a class="header-anchor" href="#price" aria-label="Permalink to &quot;Price&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Price</strong></td><td>The regular price.</td></tr><tr><td><strong>Cost</strong></td><td>What the product costs you. Shoppers don&#39;t see it.</td></tr><tr><td><strong>Special Price</strong></td><td>A sale price. It must be lower than <strong>Price</strong>.</td></tr><tr><td><strong>Special Price From</strong></td><td>The first day of the sale. Leave it empty to start the sale at once.</td></tr><tr><td><strong>Special Price To</strong></td><td>The last day of the sale. It can&#39;t be before <strong>Special Price From</strong>. Leave it empty to keep the sale running.</td></tr></tbody></table><p>The sale dates follow the channel&#39;s time zone. Configurable, grouped and bundle products have no <strong>Price</strong> section, because their price comes from the products they contain.</p><p>The <strong>Customer Group Price</strong> block, below the price fields, sets lower prices for a customer group or for larger quantities. Click <strong>Add New</strong> to add one. See <a href="./../customer/customer-group-price.html">Customer Group Pricing</a>.</p>',6)),s(o,{src:"/images/products/products-price.png",alt:"Price section with a Wholesale customer group price in the Customer Group Price block"}),t[16]||(t[16]=r('<h3 id="shipping-and-settings" tabindex="-1">Shipping and settings <a class="header-anchor" href="#shipping-and-settings" aria-label="Permalink to &quot;Shipping and settings&quot;">​</a></h3><p><strong>Shipping</strong> holds the product&#39;s <strong>Length</strong>, <strong>Width</strong>, <strong>Height</strong> and <strong>Weight</strong>. Weight is required. Configurable, grouped, bundle, virtual, downloadable and booking products don&#39;t have this section; each variant of a configurable product has its own weight.</p><p><strong>Settings</strong> holds five switches:</p><table tabindex="0"><thead><tr><th>Switch</th><th>What it does</th></tr></thead><tbody><tr><td><strong>New</strong></td><td>Marks the product as new. Product carousels on your storefront can be set to show only new products.</td></tr><tr><td><strong>Featured</strong></td><td>Marks the product as featured. Product carousels can be set to show only featured products.</td></tr><tr><td><strong>Visible Individually</strong></td><td>Gives the product its own page and lists it in categories and search. Switch it off for products you only sell as part of another product.</td></tr><tr><td><strong>Status</strong></td><td>Switch it on to sell the product. A disabled product doesn&#39;t appear on the storefront.</td></tr><tr><td><strong>Guest Checkout</strong></td><td>Lets shoppers who aren&#39;t signed in buy the product. It only works when <strong>Allow guest checkout</strong> is on in <a href="./../configure/checkout.html">Checkout</a>. If any product in the cart has it off, the shopper must sign in to check out.</td></tr></tbody></table>',4)),s(o,{src:"/images/products/products-shipping-settings.png",alt:"Shipping and Settings sections of the edit screen"}),t[17]||(t[17]=r('<p>Carousels are theme sections; see <a href="./../appearance/themes.html">Themes &amp; Sections</a>.</p><h3 id="inventories" tabindex="-1">Inventories <a class="header-anchor" href="#inventories" aria-label="Permalink to &quot;Inventories&quot;">​</a></h3><p>The <strong>Inventories</strong> section tracks the product&#39;s stock.</p><ul><li><strong>Manage Stock:</strong> switch it on to track stock. When it&#39;s off, the product is always in stock.</li><li><strong>Pending Ordered Qty:</strong> the quantity ordered but not shipped yet. It&#39;s taken off the inventory source&#39;s stock when the order ships.</li><li>One quantity field for each active inventory source. Enter the quantity you hold at each source. See <a href="./../settings/inventory-source.html">Inventory Sources</a>.</li></ul>',4)),s(o,{src:"/images/products/products-inventories.png",alt:"Inventories section with Manage Stock and a quantity for each inventory source"}),t[18]||(t[18]=r('<p>Configurable, grouped, bundle, downloadable and booking products have no <strong>Inventories</strong> section. To let shoppers order more than you hold, see <a href="./../configure/back-orders.html">Inventory</a>.</p><h3 id="rma" tabindex="-1">RMA <a class="header-anchor" href="#rma" aria-label="Permalink to &quot;RMA&quot;">​</a></h3><p><strong>Allow RMA</strong> and <strong>RMA Rules</strong> decide whether shoppers can return the product and under which rule. The section always appears for simple products, including the variants of configurable products. Configurable, grouped and bundle products have it when their type is selected in <strong>Allow Product Type For RMA</strong> in the <a href="./../configure/rma.html">RMA</a> configuration. Virtual, downloadable and booking products never have it. See <a href="./../orders/rma.html">Return Merchandise Authorization (RMA)</a>.</p><h3 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h3><p>When you have more than one channel, the <strong>Channels</strong> section lists them. Tick the channels the product is sold in. A product must be in at least one channel.</p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>Tick the categories the product belongs to. Use the search box to find a category in a long tree. The tree lists the active categories under the selected channel&#39;s root category; categories the product has in other channels&#39; trees stay assigned. See <a href="./../category/create-category.html">Categories</a>.</p>',7)),s(o,{src:"/images/products/products-categories.png",alt:"Categories section with a searchable category tree"}),t[19]||(t[19]=r('<h2 id="how-the-family-and-the-type-decide-the-fields" tabindex="-1">How the family and the type decide the fields <a class="header-anchor" href="#how-the-family-and-the-type-decide-the-fields" aria-label="Permalink to &quot;How the family and the type decide the fields&quot;">​</a></h2><p>The attribute family decides the sections and fields: each of its groups becomes a section, in the group&#39;s column and position, and each attribute in a group becomes a field. To add a field to products, create the attribute and add it to the family. See <a href="./../attribute/attribute-family.html">Attribute Families</a>.</p><p>The product type then hides the sections it doesn&#39;t use:</p><table tabindex="0"><thead><tr><th>Type</th><th>Price</th><th>Shipping</th><th>Inventories</th><th>Guest Checkout</th><th>RMA</th><th>Type&#39;s section</th></tr></thead><tbody><tr><td>Simple</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td><strong>Customizable Item</strong></td></tr><tr><td>Configurable</td><td>No</td><td>No</td><td>No</td><td>Yes</td><td>If allowed</td><td><strong>Variations</strong></td></tr><tr><td>Grouped</td><td>No</td><td>No</td><td>No</td><td>Yes</td><td>If allowed</td><td><strong>Group Products</strong></td></tr><tr><td>Bundle</td><td>No</td><td>No</td><td>No</td><td>Yes</td><td>If allowed</td><td><strong>Bundle Items</strong></td></tr><tr><td>Downloadable</td><td>Yes</td><td>No</td><td>No</td><td>No</td><td>No</td><td><strong>Downloadable Links</strong> and <strong>Downloadable Samples</strong></td></tr><tr><td>Virtual</td><td>Yes</td><td>No</td><td>Yes</td><td>Yes</td><td>No</td><td><strong>Customizable Item</strong></td></tr><tr><td>Booking</td><td>Yes</td><td>No</td><td>No</td><td>No</td><td>No</td><td>The booking section, starting with <strong>Booking Type</strong></td></tr></tbody></table>',4))])}const T=n(h,[["render",c]]);export{y as __pageData,T as default};
